('1831588e-3b92-43fa-8eba-f0daa0054a1d', 'F-1.03', 'Formulir Pendaftaran Perpindahan Penduduk', 'F-1.03 — Surat Keterangan Pindah', '{\"sections\":[{\"title\":\"Data Pemohon\",\"fields\":[{\"key\":\"no_kk\",\"label\":\"No. Kartu Keluarga\",\"type\":\"text\",\"required\":true,\"rules\":\"digits:16\",\"inputmode\":\"numeric\",\"maxlength\":16},{\"key\":\"nama_lengkap\",\"label\":\"Nama Lengkap Pemohon\",\"type\":\"text\",\"required\":true},{\"key\":\"nik\",\"label\":\"NIK\",\"type\":\"text\",\"required\":true,\"rules\":\"digits:16\",\"inputmode\":\"numeric\",\"maxlength\":16},{\"key\":\"jenis_permohonan\",\"label\":\"Jenis Permohonan\",\"type\":\"radio\",\"options\":[\"Surat Keterangan Pindah\",\"Surat Keterangan Pindah Luar Negeri (SKPLN)\",\"Surat Keterangan Tempat Tinggal (SKTT) Orang Asing\"],\"required\":true}]},{\"title\":\"Alamat Asal\",\"fields\":[{\"key\":\"asal_alamat\",\"label\":\"Asal \\u2014 Alamat (Jalan\\/Dusun)\",\"type\":\"textarea\",\"required\":false},{\"key\":\"asal_rt\",\"label\":\"RT\",\"type\":\"text\",\"required\":false},{\"key\":\"asal_rw\",\"label\":\"RW\",\"type\":\"text\",\"required\":false},{\"key\":\"asal_wilayah\",\"label\":\"Asal \\u2014 Wilayah (Provinsi \\u2192 Desa)\",\"type\":\"wilayah\"},{\"key\":\"asal_kodepos\",\"label\":\"Kode Pos\",\"type\":\"text\",\"required\":false}]},{\"title\":\"Klasifikasi Kepindahan\",\"fields\":[{\"key\":\"klasifikasi\",\"label\":\"Klasifikasi Kepindahan\",\"type\":\"radio\",\"options\":[\"Dalam satu desa\\/kelurahan\",\"Antar desa\\/kelurahan dalam satu kecamatan\",\"Antar kecamatan dalam satu kabupaten\\/kota\",\"Antar kabupaten\\/kota dalam satu provinsi\",\"Antar provinsi\"],\"required\":true}]},{\"title\":\"Alamat Pindah (Tujuan)\",\"fields\":[{\"key\":\"tujuan_alamat\",\"label\":\"Tujuan \\u2014 Alamat (Jalan\\/Dusun)\",\"type\":\"textarea\",\"required\":false},{\"key\":\"tujuan_rt\",\"label\":\"RT\",\"type\":\"text\",\"required\":false},{\"key\":\"tujuan_rw\",\"label\":\"RW\",\"type\":\"text\",\"