('20132708-5064-4696-a1f5-3f37be2fe19d', 'F-1.02', 'Formulir Pendaftaran Peristiwa Kependudukan', 'F-1.02 — KK / KTP-el / KIA / Perubahan Data', '{\"sections\":[{\"title\":\"Data Pemohon\",\"fields\":[{\"key\":\"nama_lengkap\",\"label\":\"Nama Lengkap\",\"type\":\"text\",\"required\":true},{\"key\":\"nik\",\"label\":\"Nomor Induk Kependudukan (NIK)\",\"type\":\"text\",\"required\":true,\"rules\":\"digits:16\",\"inputmode\":\"numeric\",\"maxlength\":16},{\"key\":\"no_kk\",\"label\":\"Nomor Kartu Keluarga\",\"type\":\"text\",\"required\":true,\"rules\":\"digits:16\",\"inputmode\":\"numeric\",\"maxlength\":16}]},{\"title\":\"Jenis Permohonan\",\"fields\":[{\"key\":\"jenis_permohonan\",\"label\":\"Jenis Permohonan\",\"type\":\"radio\",\"options\":[\"Kartu Keluarga\",\"KTP-el\",\"Kartu Identitas Anak (KIA)\",\"Perubahan Data\"],\"required\":true},{\"key\":\"kk_kategori\",\"label\":\"Kategori Kartu Keluarga\",\"type\":\"select\",\"options\":[\"Baru - Membentuk Keluarga Baru\",\"Baru - Penggantian Kepala Keluarga\",\"Baru - Pisah KK\",\"Baru - Pindah Datang\",\"Baru - WNI dari Luar Negeri karena Pindah\",\"Baru - Rentan Adminduk\",\"Perubahan - Menumpang Dalam KK\",\"Perubahan - Peristiwa Penting\",\"Perubahan - Perubahan Elemen Data\",\"Hilang\",\"Rusak\"],\"required\":false,\"showIf\":{\"field\":\"jenis_permohonan\",\"in\":[\"Kartu Keluarga\"]}},{\"key\":\"ktp_kategori\",\"label\":\"Kategori KTP-el\",\"type\":\"select\",\"options\":[\"Baru\",\"Pindah Datang\",\"Hilang\",\"Rusak\"],\"required\":false,\"showIf\":{\"field\":\"jenis_permohonan\",\"in\":[\"KTP-el\"]}},{\"key\":\"kia_kategori\",\"label\":\"Kategori KIA\",\"type\":\"select\",\"options\":[\"Baru\",\"Hilang\",\"Rusak\"],\"required\":false,\"showIf\":{\"field\":\"jenis_permohonan\",\"in\":[\"Kartu Identitas Anak (KIA)\"]}},{\"key\":\"perubahan_kategori\",\"label\":\"Perubahan Data\",\"type\":\"select\",\"options\":[\"Kartu Keluarga\",\"KTP-el\",\"KIA\"],\"required\":false,\"showIf\":{\"field\":\"jenis_permohonan\"